11	// Regression coverage for the shutdown boundary where the reader delivers
12	// log bytes and the terminal status of the stream in the SAME Read call.
13	// A clean EOF arriving together with the final bytes is normal completion
14	// (including a final line that has no trailing newline), while a non-EOF
15	// read fault arriving with identical bytes must keep every newline-ended
16	// line but must never turn the trailing fragment into an event or a line
17	// failure: whether the fragment parses as a complete, field-valid JSON
18	// object is irrelevant, because it belongs to the failed read.
19	//
20	// Every scenario is scripted through scriptReader/failWriter from
21	// normalize_io_test.go, so the boundary reproduces deterministically
22	// offline without real pipes, networks, or device failures.
23	
24	// mixedCompleteLines holds every kind of complete physical line:
25	//
26	//	line 1: a valid log
27	//	line 2: a blank line (no output, but it keeps its physical line number)
28	//	line 3: a field-invalid log (failure result with a reason)
29	//
30	// trailingFragment is a complete, field-valid JSON object WITHOUT a trailing
31	// newline: at a clean EOF it is the final complete log; under a read fault it
32	// is a fragment of the failed read.
33	func mixedCompleteLinesAndFragment() (complete, fragment string) {
34		complete = validLog("a") + "\n" +
35			"\n" +
36			`{"timestamp":"not-a-time","action":"b"}` + "\n"
37		fragment = `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-fragment"}`
38		return complete, fragment
39	}
40	
41	// The same bytes delivered in one Read, terminated by a clean EOF, are
42	// normal completion: every newline-ended line is processed in physical line
43	// order, the blank line only reserves its number, and the trailing
44	// newline-less JSON log still produces a result rather than being dropped.
45	func TestNormalizeIOEOFWithBytesInSameRead(t *testing.T) {
46		complete, fragment := mixedCompleteLinesAndFragment()
47		src := &scriptReader{steps: []scriptStep{
48			// One step: all bytes and io.EOF become available together.
49			{data: []byte(complete + fragment), err: io.EOF},
50		}}
51		var out bytes.Buffer
52		failures, err := NormalizeReader(src, &out)
53		if err != nil {
54			t.Fatalf("bytes delivered with a clean EOF are normal completion, got %v", err)
55		}
56		if failures != 1 {
57			t.Fatalf("only the one invalid complete line counts, got %d", failures)
58		}
59		results := decodeResults(t, out.Bytes())
60		if len(results) != 3 {
61			t.Fatalf("blank line emits nothing but the two valid logs and the invalid line do: %#v", results)
62		}
63		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
64			t.Fatalf("line 1 must be the first valid log: %#v", results[0])
65		}
66		if eventOf(t, results[0])["action"] != "a" {
67			t.Fatalf("line 1 content/order mismatch: %#v", results[0])
68		}
69		if results[1]["line"] != float64(3) || results[1]["ok"] != false {
70			t.Fatalf("blank line 2 must reserve a number so the invalid log is line 3: %#v", results[1])
71		}
72		if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
73			t.Fatalf("invalid line must carry its reason, got %q", msg)
74		}
75		// The trailing newline-less log is a complete line at EOF and must not
76		// be lost merely because EOF arrived in the same Read.
77		if results[2]["line"] != float64(4) || results[2]["ok"] != true {
78			t.Fatalf("trailing newline-less log must be processed as physical line 4: %#v", results[2])
79		}
80		if eventOf(t, results[2])["action"] != "tail-fragment" {
81			t.Fatalf("trailing log content mismatch: %#v", results[2])
82		}
83	}
84	
85	// Identical bytes delivered with a non-EOF read fault must end differently
86	// from a clean EOF: the newline-ended lines survive untouched and stay
87	// byte-for-byte identical to a healthy read of those same lines, while the
88	// trailing fragment is neither an event nor a failure even though it is a
89	// valid JSON object with every required field.
90	func TestNormalizeIOReadFaultWithBytesInSameRead(t *testing.T) {
91		complete, fragment := mixedCompleteLinesAndFragment()
92		src := &scriptReader{steps: []scriptStep{
93			// One step: complete lines, a valid-JSON fragment, and the fault
94			// all become available in the same Read.
95			{data: []byte(complete + fragment), err: errSimulatedRead},
96		}}
97		var out bytes.Buffer
98		failures, err := NormalizeReader(src, &out)
99		if err == nil {
100			t.Fatalf("a read fault must not be reported as normal completion")
101		}
102		if !errors.Is(err, ErrLogRead) {
103			t.Fatalf("caller must recognize ErrLogRead, got %v", err)
104		}
105		if !errors.Is(err, errSimulatedRead) {
106			t.Fatalf("the reader's original cause must stay reachable, got %v", err)
107		}
108		if errors.Is(err, ErrLogWrite) {
109			t.Fatalf("a healthy writer must not tag the result as a write failure: %v", err)
110		}
111		if !strings.Contains(err.Error(), errSimulatedRead.Error()) {
112			t.Fatalf("error text must retain the original read cause, got %q", err.Error())
113		}
114		if failures != 1 {
115			t.Fatalf("the valid-JSON fragment must not add a failure; only the invalid complete line counts, got %d", failures)
116		}
117	
118		// The fault must neither swallow already-delivered complete lines nor
119		// turn them into failures: output must match a healthy read of the very
120		// same complete lines exactly, including order and physical numbers.
121		var healthy bytes.Buffer
122		healthyFailures, healthyErr := NormalizeReader(strings.NewReader(complete), &healthy)
123		if healthyErr != nil || healthyFailures != 1 {
124			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
125		}
126		if !bytes.Equal(out.Bytes(), healthy.Bytes()) {
127			t.Fatalf("fault run output must equal a healthy read of the complete lines:\nfault:   %q\nhealthy: %q", out.String(), healthy.String())
128		}
129	
130		results := decodeResults(t, out.Bytes())
131		if len(results) != 2 {
132			t.Fatalf("only the two non-blank complete lines may be emitted, got %#v", results)
133		}
134		if results[0]["line"] != float64(1) || results[0]["ok"] != true ||
135			results[1]["line"] != float64(3) || results[1]["ok"] != false {
136			t.Fatalf("delivered lines keep their healthy-read order, numbers and outcomes: %#v", results)
137		}
138		if bytes.Contains(out.Bytes(), []byte("tail-fragment")) {
139			t.Fatalf("the trailing valid-JSON fragment belongs to the failed read and must not become an event or failure record: %q", out.String())
140		}
141	}
142	
143	// A newline-less, fully valid JSON object alone with a read fault proves the
144	// admission rule is line completeness at the stream boundary, not whether
145	// the text parses: there must be no per-line output and no failure count,
146	// while the stream fault still reaches the caller.
147	func TestNormalizeIOValidJSONFragmentOnlyUnderFault(t *testing.T) {
148		fragment := `{"timestamp":"2026-01-02T00:00:00Z","action":"lonely-fragment"}`
149		src := &scriptReader{steps: []scriptStep{
150			{data: []byte(fragment), err: errSimulatedRead},
151		}}
152		var out bytes.Buffer
153		failures, err := NormalizeReader(src, &out)
154		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
155			t.Fatalf("want ErrLogRead wrapping the read cause, got %v", err)
156		}
157		if failures != 0 {
158			t.Fatalf("a parseable failed-read fragment must not count as a line failure, got %d", failures)
159		}
160		if out.Len() != 0 {
161			t.Fatalf("no complete line means no output at all, got %q", out.String())
162		}
163	
164		// The same fragment at a clean EOF is accepted: the differing outcome
165		// comes solely from how the stream ended.
166		var healthy bytes.Buffer
167		healthyFailures, healthyErr := NormalizeReader(strings.NewReader(fragment), &healthy)
168		if healthyErr != nil || healthyFailures != 0 {
169			t.Fatalf("same bytes at clean EOF must be a healthy read, got failures=%d err=%v", healthyFailures, healthyErr)
170		}
171		results := decodeResults(t, healthy.Bytes())
172		if len(results) != 1 || results[0]["ok"] != true {
173			t.Fatalf("clean-EOF fragment must be one successful result: %#v", results)
174		}
175	}
176	
177	// When the read fault and a shutdown write fault both happen, the read cause
178	// stays the primary error (ErrLogRead plus the original cause are reachable
179	// via errors.Is); the later write cause appears only in the message text and
180	// must not replace the read cause. The processed failure count is frozen at
181	// whatever the complete lines already produced. Unlike the two-step variant
182	// elsewhere, the fault and its complete-line bytes arrive in a single Read.
183	func TestNormalizeIOReadFaultWithBytesWinsOverFlushFault(t *testing.T) {
184		complete, fragment := mixedCompleteLinesAndFragment()
185		src := &scriptReader{steps: []scriptStep{
186			{data: []byte(complete + fragment), err: errSimulatedRead},
187		}}
188		// Small records stay buffered in the 4096-byte writer, so the rejecting
189		// writer is first touched by the shutdown flush after the read fault.
190		w := &failWriter{err: errSimulatedWrite}
191		failures, err := NormalizeReader(src, w)
192		if err == nil {
193			t.Fatalf("expected the read failure, got nil")
194		}
195		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
196			t.Fatalf("read failure and its cause must remain primary, got %v", err)
197		}
198		if errors.Is(err, ErrLogWrite) || errors.Is(err, errSimulatedWrite) {
199			t.Fatalf("the later flush fault must not replace or shadow the read cause: %v", err)
200		}
201		msg := err.Error()
202		if !strings.Contains(msg, errSimulatedRead.Error()) {
203			t.Fatalf("message must name the read cause, got %q", msg)
204		}
205		if !strings.Contains(msg, errSimulatedWrite.Error()) {
206			t.Fatalf("the shutdown write fault must remain visible in the message text, got %q", msg)
207		}
208		if failures != 1 {
209			t.Fatalf("processed failure count must freeze at the one invalid complete line, got %d", failures)
210		}
211	}
