1	package relayproof
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9		"testing"
10	)
11	
12	// Regression coverage for the output end that acknowledges only a prefix of
13	// the final result batch and then returns a nil error. A Writer that reports
14	// (n < len(p), nil) breaks the io.Writer contract, but the shutdown flush is
15	// the only write for a short-log stream (records stay buffered), so the
16	// interruption must be surfaced as a stream write failure rather than normal
17	// completion. The two channels NormalizeReader offers its caller stay
18	// independent: a nil output error does not prove the batch arrived whole,
19	// and the invalid-log count is a property of processed input, never a count
20	// of the failure records that made it to the output.
21	//
22	// Everything is scripted in-process (scriptReader/failWriter family plus the
23	// nilErrorPrefixWriter below), so the boundary reproduces deterministically
24	// without real pipes, networks, or device failures.
25	
26	// nilErrorPrefixWriter accepts at most allowBytes bytes across all Write
27	// calls, records everything accepted, and always returns a nil error — even
28	// when it accepts nothing or only a prefix of the offered bytes. This models
29	// an output end that goes away mid-batch without setting the error value
30	// (an io.Writer contract violation that callers must still survive): a
31	// well-behaved sink must turn the short acknowledgement into io.ErrShortWrite
32	// instead of taking the nil error as proof that delivery completed.
33	type nilErrorPrefixWriter struct {
34		buf        bytes.Buffer
35		allowBytes int
36		writes     int
37	}
38	
39	func (w *nilErrorPrefixWriter) Write(p []byte) (int, error) {
40		w.writes++
41		if w.allowBytes <= 0 {
42			return 0, nil
43		}
44		n := len(p)
45		if n > w.allowBytes {
46			n = w.allowBytes
47		}
48		w.buf.Write(p[:n])
49		w.allowBytes -= n
50		return n, nil
51	}
52	
53	// shortWriteBatchInput builds a small batch of short logs: valid logs around
54	// a single field-invalid complete line. The blank line keeps a physical line
55	// number but emits nothing.
56	func shortWriteBatchInput() string {
57		return validLog("a") + "\n" +
58			"\n" +
59			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
60			validLog("c") + "\n"
61	}
62	
63	// expectShortWriteInterruption checks the common contract for any output that
64	// only partially acknowledges the final flush: ErrLogWrite with
65	// io.ErrShortWrite in its chain, never normal completion and never a read
66	// failure, no fabricated extra log failure, and no retry storm against the
67	// broken writer.
68	func expectShortWriteInterruption(t *testing.T, w *nilErrorPrefixWriter, failures, wantFailures int, err error) {
69		t.Helper()
70		if err == nil {
71			t.Fatalf("a partially acknowledged final flush must not return as normal completion, got nil (failures=%d)", failures)
72		}
73		if !errors.Is(err, ErrLogWrite) {
74			t.Fatalf("caller must recognize the interruption via errors.Is(err, ErrLogWrite), got %v", err)
75		}
76		if !errors.Is(err, io.ErrShortWrite) {
77			t.Fatalf("error chain must retain io.ErrShortWrite so the cause is a silent short write, got %v", err)
78		}
79		if errors.Is(err, ErrLogRead) {
80			t.Fatalf("a healthy reader must not classify a write interruption as ErrLogRead: %v", err)
81		}
82		if failures != wantFailures {
83			t.Fatalf("invalid-log count must describe processed input regardless of delivery, got %d, want %d", failures, wantFailures)
84		}
85		if w.writes != 1 {
86			t.Fatalf("the sticky flush failure must stop after one write attempt, got %d calls", w.writes)
87		}
88	}
89	
90	// When the final batch is flushed at clean input EOF and the output accepts
91	// only a leading run of the offered bytes with a nil error, the caller must
92	// still receive ErrLogWrite carrying io.ErrShortWrite. Accepted bytes may
93	// remain, including an incomplete final JSON record; the interruption must
94	// not fabricate an additional per-log failure, and all-valid input still
95	// reports zero invalid logs even though none of the results is guaranteed to
96	// have arrived.
97	func TestNormalizeIOShortWriteNilErrorOnFinalFlush(t *testing.T) {
98		allValid := validLog("a") + "\n" + validLog("b") + "\n"
99	
100		t.Run("accepts no bytes at all", func(t *testing.T) {
101			w := &nilErrorPrefixWriter{allowBytes: 0}
102			failures, err := NormalizeReader(strings.NewReader(allValid), w)
103			expectShortWriteInterruption(t, w, failures, 0, err)
104			if w.buf.Len() != 0 {
105				t.Fatalf("zero acknowledged bytes must leave zero output, got %q", w.buf.String())
106			}
107		})
108	
109		t.Run("accepts a prefix of the batch", func(t *testing.T) {
110			firstRecord := encodedRecord(t, 1, validLog("a"))
111			var healthy bytes.Buffer
112			if _, err := NormalizeReader(strings.NewReader(allValid), &healthy); err != nil {
113				t.Fatalf("test setup: healthy reference run failed: %v", err)
114			}
115			total := healthy.Len()
116			cuts := []struct {
117				name string
118				cut  int
119			}{
120				{"mid first record", 5},
121				{"whole first record plus fragment", len(firstRecord) + 5},
122				{"last JSON of the batch cut open", total - 3},
123			}
124			for _, tc := range cuts {
125				t.Run(tc.name, func(t *testing.T) {
126					cut := tc.cut
127					w := &nilErrorPrefixWriter{allowBytes: cut}
128					failures, err := NormalizeReader(strings.NewReader(allValid), w)
129					expectShortWriteInterruption(t, w, failures, 0, err)
130					if w.buf.Len() != cut {
131						t.Fatalf("exactly the acknowledged prefix must remain, got %d bytes, want %d", w.buf.Len(), cut)
132					}
133					// The retained bytes are an unmodified prefix of a healthy
134					// run's output, ending wherever the output stopped accepting.
135					if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
136						t.Fatalf("accepted bytes must be the unmodified prefix of complete output:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
137					}
138					// The tail is allowed to be an incomplete final JSON record;
139					// the interruption must not have added a failure record.
140					results := decodePrefix(t, w.buf.Bytes())
141					for _, r := range results {
142						if r["ok"] == false {
143							t.Fatalf("write interruption must not add a log failure record, got %#v", r)
144						}
145					}
146				})
147			}
148		})
149	}
150	
151	// The invalid-log count belongs to processed input, not to what the output
152	// managed to receive: with one field-invalid complete line already processed,
153	// a partially acknowledged final flush still reports exactly one invalid log
154	// even when its failure result never fully reaches the output — and reports
155	// zero when every processed log was valid. The count is neither "failure
156	// records written" nor inflated by undelivered success results.
157	func TestNormalizeIOShortWriteKeepsInvalidLogCountIndependent(t *testing.T) {
158		cases := []struct {
159			name         string
160			input        string
161			wantFailures int
162		}{
163			{"all logs valid", validLog("a") + "\n" + validLog("b") + "\n", 0},
164			{"one field-invalid log processed", shortWriteBatchInput(), 1},
165		}
166		for _, tc := range cases {
167			t.Run(tc.name, func(t *testing.T) {
168				t.Run("no bytes accepted", func(t *testing.T) {
169					w := &nilErrorPrefixWriter{allowBytes: 0}
170					failures, err := NormalizeReader(strings.NewReader(tc.input), w)
171					expectShortWriteInterruption(t, w, failures, tc.wantFailures, err)
172					if w.buf.Len() != 0 {
173						t.Fatalf("nothing should be retained, got %q", w.buf.String())
174					}
175				})
176	
177				t.Run("prefix accepted", func(t *testing.T) {
178					// Accept a small opening fragment only, so with the invalid
179					// line present its failure result is certainly not among the
180					// whole records that arrived.
181					w := &nilErrorPrefixWriter{allowBytes: 5}
182					failures, err := NormalizeReader(strings.NewReader(tc.input), w)
183					expectShortWriteInterruption(t, w, failures, tc.wantFailures, err)
184					if w.buf.Len() != 5 {
185						t.Fatalf("the acknowledged 5-byte fragment must remain, got %d", w.buf.Len())
186					}
187					whole := decodePrefix(t, w.buf.Bytes())
188					if len(whole) != 0 {
189						t.Fatalf("a 5-byte prefix cannot contain a whole record, got %#v", whole)
190					}
191				})
192			})
193		}
194	}
195	
196	// The same inputs handed to an output that receives the whole batch end
197	// normally: nil error, results in input order keyed by original physical line
198	// numbers (the blank line reserves a number), valid logs carry normalized
199	// events, the invalid log carries only its own reason, and later valid logs
200	// still succeed. Complete vs. incomplete delivery changes only the stream
201	// error and what physically arrived — never the legality verdict for the same
202	// processed batch.
203	func TestNormalizeIOFullDeliverySameBatchCompletesNormally(t *testing.T) {
204		cases := []struct {
205			name         string
206			input        string
207			wantFailures int
208		}{
209			{"all valid", validLog("a") + "\n" + validLog("b") + "\n", 0},
210			{"one invalid among valid", shortWriteBatchInput(), 1},
211		}
212		for _, tc := range cases {
213			t.Run(tc.name, func(t *testing.T) {
214				var out bytes.Buffer
215				failures, err := NormalizeReader(strings.NewReader(tc.input), &out)
216				if err != nil {
217					t.Fatalf("fully acknowledged output must complete with nil error, got %v", err)
218				}
219				if failures != tc.wantFailures {
220					t.Fatalf("invalid-log count on healthy delivery = %d, want %d", failures, tc.wantFailures)
221				}
222				results := decodeResults(t, out.Bytes())
223	
224				if tc.name == "all valid" {
225					if len(results) != 2 {
226						t.Fatalf("expected 2 results, got %#v", results)
227					}
228					if results[0]["line"] != float64(1) || results[0]["ok"] != true ||
229						results[1]["line"] != float64(2) || results[1]["ok"] != true {
230						t.Fatalf("results must keep physical line order: %#v", results)
231					}
232					if eventOf(t, results[0])["action"] != "a" || eventOf(t, results[1])["action"] != "b" {
233						t.Fatalf("valid logs must carry normalized events in order: %#v", results)
234					}
235					return
236				}
237	
238				// Blank physical line 2 emits nothing; line numbers stay physical.
239				if len(results) != 3 {
240					t.Fatalf("blank line emits nothing but the other three lines do, got %#v", results)
241				}
242				if results[0]["line"] != float64(1) || results[0]["ok"] != true {
243					t.Fatalf("line 1 must be the first valid log: %#v", results[0])
244				}
245				if eventOf(t, results[0])["action"] != "a" {
246					t.Fatalf("line 1 event mismatch: %#v", results[0])
247				}
248				if results[1]["line"] != float64(3) || results[1]["ok"] != false {
249					t.Fatalf("field-invalid line must be a failure, got %#v", results[1])
250				}
251				if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
252					t.Fatalf("invalid log must carry only its own failure reason, got %q", msg)
253				}
254				if _, exists := results[1]["event"]; exists {
255					t.Fatalf("invalid log must not carry an event: %#v", results[1])
256				}
257				if results[2]["line"] != float64(4) || results[2]["ok"] != true {
258					t.Fatalf("later valid log must still succeed as physical line 4: %#v", results[2])
259				}
260				if eventOf(t, results[2])["action"] != "c" {
261					t.Fatalf("later valid log must carry its normalized event: %#v", results[2])
262				}
263			})
264		}
265	}
266	
267	// The interrupted run and the healthy run judge the exact same processed
268	// batch identically: per-line legality, physical line numbers, order, and
269	// result bytes agree up to the point the broken output stopped accepting.
270	func TestNormalizeIOShortAndFullDeliveryShareLegality(t *testing.T) {
271		input := shortWriteBatchInput()
272	
273		var healthy bytes.Buffer
274		healthyFailures, healthyErr := NormalizeReader(strings.NewReader(input), &healthy)
275		if healthyErr != nil || healthyFailures != 1 {
276			t.Fatalf("test setup: healthy reference run: failures=%d err=%v", healthyFailures, healthyErr)
277		}
278	
279		for _, cut := range []int{0, 5, len(encodedRecord(t, 1, validLog("a"))) + 5} {
280			t.Run(fmt.Sprintf("cut_%d", cut), func(t *testing.T) {
281				w := &nilErrorPrefixWriter{allowBytes: cut}
282				failures, err := NormalizeReader(strings.NewReader(input), w)
283				expectShortWriteInterruption(t, w, failures, 1, err)
284				if w.buf.Len() != cut {
285					t.Fatalf("acknowledged prefix length = %d, want %d", w.buf.Len(), cut)
286				}
287				if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
288					t.Fatalf("interrupted output must be a prefix of healthy output:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
289				}
290			})
291		}
292	}
