1	package relayproof
2	
3	// Regression coverage for nil-error short acknowledgements while writing a
4	// result larger than the 4096-byte buffering writer. Such a result bypasses
5	// the buffer and is handed to the underlying io.Writer in one call; bufio
6	// retries a (n < len(p), nil) answer forever, so an output end that accepts
7	// nothing (or only a prefix) without setting an error previously made
8	// NormalizeReader spin without returning. The fix turns the broken
9	// acknowledgement into io.ErrShortWrite at the boundary, ending the run with
10	// ErrLogWrite on the first short answer.
11	//
12	// The assertions pin the contract from the task:
13	//   - zero-byte and non-empty-prefix nil acknowledgements both stop the run
14	//     immediately, with an error matching ErrLogWrite AND io.ErrShortWrite;
15	//   - an output that could accept again after the broken answer is neither
16	//     retried nor allowed to turn the anomaly into success;
17	//   - a concrete output error stays the cause and is never replaced by
18	//     io.ErrShortWrite;
19	//   - accepted bytes remain the unmodified prefix of normal output, complete
20	//     records keep physical line order, and an incomplete final JSON may
21	//     remain without an extra fabricated log-failure record;
22	//   - the failure count describes processed input: an invalid log already
23	//     normalized counts even when its failure result did not fully arrive,
24	//     later unprocessed invalid logs do not count, and a legal long log does
25	//     not become illegal because of the write fault;
26	//   - under the source-CIDR filter a long out-of-network event is never
27	//     written (so it cannot trigger the fault), while a long admitted event
28	//     obeys the same short-write rules and fully arrives on healthy output.
29	//
30	// Everything is scripted in-process with the helpers from
31	// normalize_io_test.go / normalize_io_shortwrite_regression_test.go.
32	
33	import (
34		"bytes"
35		"encoding/json"
36		"errors"
37		"fmt"
38		"io"
39		"strings"
40		"testing"
41	)
42	
43	// bigSourcedLog builds a legal log whose normalized result exceeds the 4096
44	// byte buffer: a 5000-character extra field is the extension evidence. With
45	// ip != "" the log also carries a source_ip for filter scenarios.
46	func bigSourcedLog(action, ip string) string {
47		source := ""
48		if ip != "" {
49			source = fmt.Sprintf(`,"source_ip":%q`, ip)
50		}
51		return fmt.Sprintf(`{"timestamp":"2026-01-02T00:00:00Z","action":%q%s,"pad":%q}`,
52			action, source, strings.Repeat("p", 5000))
53	}
54	
55	// expectLongShortWriteFailure is the mid-stream analogue of
56	// expectShortWriteInterruption: the error must classify as a write failure
57	// carrying io.ErrShortWrite, never a read failure, and processing must stop
58	// after exactly wantWrites physical attempts (no retry loop).
59	func expectLongShortWriteFailure(t *testing.T, w *nilErrorPrefixWriter, failures, wantFailures, wantWrites int, err error) {
60		t.Helper()
61		if err == nil {
62			t.Fatalf("a nil-error short write on a long result must not end as normal completion, got nil (failures=%d)", failures)
63		}
64		if !errors.Is(err, ErrLogWrite) {
65			t.Fatalf("caller must recognize the interruption via errors.Is(err, ErrLogWrite), got %v", err)
66		}
67		if !errors.Is(err, io.ErrShortWrite) {
68			t.Fatalf("error chain must retain io.ErrShortWrite for a nil-error short acknowledgement, got %v", err)
69		}
70		if errors.Is(err, ErrLogRead) {
71			t.Fatalf("a healthy reader must not classify a write interruption as ErrLogRead: %v", err)
72		}
73		if failures != wantFailures {
74			t.Fatalf("invalid-log count must describe processed input regardless of delivery, got %d, want %d", failures, wantFailures)
75		}
76		if w.writes != wantWrites {
77			t.Fatalf("processing must stop on the first nil-error short acknowledgement, got %d write calls, want %d", w.writes, wantWrites)
78		}
79	}
80	
81	// decodeAvailable decodes every whole record a possibly truncated output
82	// contains, accepting either a trailing syntax error (cut mid-record), a
83	// clean record boundary, or empty output. The interruption guarantees never
84	// add a failure record regardless of where the cut lands.
85	func decodeAvailable(t *testing.T, data []byte) []map[string]any {
86		t.Helper()
87		var results []map[string]any
88		dec := json.NewDecoder(bytes.NewReader(data))
89		for {
90			var m map[string]any
91			if err := dec.Decode(&m); err != nil {
92				return results
93			}
94			results = append(results, m)
95		}
96	}
97	
98	// A single legal log longer than the buffer, offered to an output that
99	// accepts ZERO bytes with a nil error, must end with ErrLogWrite carrying
100	// io.ErrShortWrite after exactly one physical write: no busy retry, and the
101	// legal log does not become a failure.
102	func TestNormalizeIOLongResultZeroByteNilErrorStops(t *testing.T) {
103		line := bigSourcedLog("long-a", "")
104		rec := encodedRecord(t, 1, line)
105		if len(rec) <= 4096 {
106			t.Fatalf("test setup: encoded result must exceed the 4096-byte buffer, got %d", len(rec))
107		}
108		w := &nilErrorPrefixWriter{allowBytes: 0}
109		failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
110		expectLongShortWriteFailure(t, w, failures, 0, 1, err)
111		if w.buf.Len() != 0 {
112			t.Fatalf("zero acknowledged bytes must leave zero output, got %q", w.buf.String())
113		}
114	}
115	
116	// Non-empty-prefix nil acknowledgements on a long result follow the same rule
117	// at every cut: stop on the first answer, keep exactly the acknowledged
118	// prefix of a healthy run's output, allow an incomplete final JSON, and never
119	// add a failure record. Both a lone long line and a small complete record
120	// preceding the interrupted long line are covered.
121	func TestNormalizeIOLongResultPrefixNilErrorKeepsPrefix(t *testing.T) {
122		t.Run("single long line", func(t *testing.T) {
123			line := bigSourcedLog("long-a", "")
124			rec := encodedRecord(t, 1, line)
125			var healthy bytes.Buffer
126			if _, err := NormalizeReader(strings.NewReader(line+"\n"), &healthy); err != nil {
127				t.Fatalf("test setup: healthy reference run failed: %v", err)
128			}
129			for _, cut := range []int{5, 120, len(rec) - 3} {
130				t.Run(fmt.Sprintf("cut_%d", cut), func(t *testing.T) {
131					w := &nilErrorPrefixWriter{allowBytes: cut}
132					failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
133					expectLongShortWriteFailure(t, w, failures, 0, 1, err)
134					if w.buf.Len() != cut {
135						t.Fatalf("exactly the acknowledged prefix must remain, got %d bytes, want %d", w.buf.Len(), cut)
136					}
137					if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
138						t.Fatalf("accepted bytes must be the unmodified prefix of healthy output:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
139					}
140					for _, r := range decodeAvailable(t, w.buf.Bytes()) {
141						if r["ok"] == false {
142							t.Fatalf("write interruption must not add a log failure record, got %#v", r)
143						}
144					}
145				})
146			}
147		})
148	
149		t.Run("small record delivered before the interrupted long line", func(t *testing.T) {
150			small := validLog("a")
151			line := bigSourcedLog("long-b", "")
152			input := small + "\n" + line + "\n"
153	
154			var healthy bytes.Buffer
155			firstRecord := encodedRecord(t, 1, small)
156			if _, err := NormalizeReader(strings.NewReader(input), &healthy); err != nil {
157				t.Fatalf("test setup: healthy reference run failed: %v", err)
158			}
159			// Encoding the long line flushes the buffered small record together
160			// with the first buffer-fill of the long line in ONE physical write
161			// of 4096 bytes; every cut below lands inside that single offer.
162			for _, cut := range []int{0, 5, len(firstRecord) + 10, 4096 - 1} {
163				t.Run(fmt.Sprintf("cut_%d", cut), func(t *testing.T) {
164					w := &nilErrorPrefixWriter{allowBytes: cut}
165					failures, err := NormalizeReader(strings.NewReader(input), w)
166					expectLongShortWriteFailure(t, w, failures, 0, 1, err)
167					if w.buf.Len() != cut {
168						t.Fatalf("exactly the acknowledged prefix must remain, got %d, want %d", w.buf.Len(), cut)
169					}
170					if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
171						t.Fatalf("accepted bytes must be the unmodified prefix of healthy output:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
172					}
173					whole := decodeAvailable(t, w.buf.Bytes())
174					for _, r := range whole {
175						if r["ok"] == false {
176							t.Fatalf("write interruption must not add a log failure record, got %#v", r)
177						}
178					}
179					if cut >= len(firstRecord) {
180						if len(whole) != 1 || whole[0]["line"] != float64(1) || whole[0]["ok"] != true {
181							t.Fatalf("the complete small record must survive in physical line order, got %#v", whole)
182						}
183						if eventOf(t, whole[0])["action"] != "a" {
184							t.Fatalf("surviving record must be the genuine first log, got %#v", whole[0])
185						}
186					}
187				})
188			}
189		})
190	}
191	
192	// The invalid-log count belongs to processed input around the long-write
193	// fault:
194	//  1. an invalid log normalized before the fault counts even when its failure
195	//     result is cut off mid-record;
196	//  2. the same invalid log counts when its failure result happened to arrive
197	//     whole just before the cut;
198	//  3. invalid logs never reached because the long write failed first do not
199	//     count, and the legal long log does not become a failure itself.
200	func TestNormalizeIOLongResultShortWriteFailureCountSemantics(t *testing.T) {
201		invalid := `{"timestamp":"not-a-time","action":"bad"}`
202		failureRecord := encodedRecord(t, 2, invalid)
203	
204		t.Run("invalid already processed, failure result cut off", func(t *testing.T) {
205			line1 := bigSourcedLog("long-a", "")
206			encoded1 := encodedRecord(t, 1, line1)
207			line3 := bigSourcedLog("long-c", "")
208			// Line 1 is one full physical write; while line 3 is encoded the
209			// buffered line-2 failure record is flushed with line 3's prefix, and
210			// only 5 of those bytes are accepted before the nil-error stop.
211			w := &nilErrorPrefixWriter{allowBytes: len(encoded1) + 5}
212			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+invalid+"\n"+line3+"\n"), w)
213			expectLongShortWriteFailure(t, w, failures, 1, 2, err)
214			whole := decodeAvailable(t, w.buf.Bytes())
215			if len(whole) != 1 || whole[0]["ok"] != true {
216				t.Fatalf("only the fully delivered line 1 may decode whole: %#v", whole)
217			}
218			if eventOf(t, whole[0])["action"] != "long-a" {
219				t.Fatalf("surviving record must be the genuine first log, got %#v", whole[0])
220			}
221		})
222	
223		t.Run("invalid already processed, failure result delivered whole", func(t *testing.T) {
224			line1 := bigSourcedLog("long-a", "")
225			encoded1 := encodedRecord(t, 1, line1)
226			line3 := bigSourcedLog("long-c", "")
227			w := &nilErrorPrefixWriter{allowBytes: len(encoded1) + len(failureRecord)}
228			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+invalid+"\n"+line3+"\n"), w)
229			expectLongShortWriteFailure(t, w, failures, 1, 2, err)
230			whole := decodeAvailable(t, w.buf.Bytes())
231			if len(whole) != 2 {
232				t.Fatalf("line 1 and the complete failure record must decode, got %#v", whole)
233			}
234			if whole[0]["line"] != float64(1) || whole[0]["ok"] != true {
235				t.Fatalf("line 1 mismatch: %#v", whole[0])
236			}
237			if whole[1]["line"] != float64(2) || whole[1]["ok"] != false {
238				t.Fatalf("the invalid log must keep physical line number 2: %#v", whole[1])
239			}
240			if _, exists := whole[1]["event"]; exists {
241				t.Fatalf("failure record must not carry an event: %#v", whole[1])
242			}
243			if msg, _ := whole[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
244				t.Fatalf("failure record must keep its own reason, got %q", msg)
245			}
246		})
247	
248		t.Run("later invalid logs are never processed", func(t *testing.T) {
249			line1 := bigSourcedLog("long-a", "")
250			// The very first physical write is already cut off, so neither later
251			// invalid line is ever normalized.
252			w := &nilErrorPrefixWriter{allowBytes: 0}
253			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+invalid+"\n"+invalid+"\n"), w)
254			expectLongShortWriteFailure(t, w, failures, 0, 1, err)
255			if w.buf.Len() != 0 {
256				t.Fatalf("nothing should have been retained, got %q", w.buf.String())
257			}
258		})
259	}
260	
261	// nilShortThenRecoverWriter returns a nil-error short acknowledgement on its
262	// first Write and would fully accept every later offer. A correct run must
263	// never take the later offers: the anomaly is a deterministic failure, not a
264	// reason to wait for the output end to recover.
265	type nilShortThenRecoverWriter struct {
266		buf         bytes.Buffer
267		firstAccept int // bytes acknowledged on the first (short, nil) Write
268		writes      int
269	}
270	
271	func (w *nilShortThenRecoverWriter) Write(p []byte) (int, error) {
272		w.writes++
273		if w.writes == 1 {
274			n := w.firstAccept
275			if n >= len(p) {
276				n = len(p) - 1
277			}
278			w.buf.Write(p[:n])
279			return n, nil
280		}
281		w.buf.Write(p)
282		return len(p), nil
283	}
284	
285	// Even an output end that could keep receiving afterwards must not make the
286	// run succeed: the first nil-error short answer ends it with both write
287	// markers, the acknowledged prefix alone remains, and no second write occurs.
288	func TestNormalizeIOLongResultNilErrorShortNotRetriedEvenIfOutputRecovers(t *testing.T) {
289		line := bigSourcedLog("long-a", "")
290		rec := encodedRecord(t, 1, line)
291	
292		var healthy bytes.Buffer
293		if _, err := NormalizeReader(strings.NewReader(line+"\n"), &healthy); err != nil {
294			t.Fatalf("test setup: healthy reference run failed: %v", err)
295		}
296	
297		for _, firstAccept := range []int{0, 120, len(rec) - 3} {
298			t.Run(fmt.Sprintf("first_accept_%d", firstAccept), func(t *testing.T) {
299				w := &nilShortThenRecoverWriter{firstAccept: firstAccept}
300				failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
301				if err == nil || !errors.Is(err, ErrLogWrite) || !errors.Is(err, io.ErrShortWrite) {
302					t.Fatalf("the first nil short acknowledgement must end the run as a short write, got %v", err)
303				}
304				if failures != 0 {
305					t.Fatalf("a legal long log must not become a failure, got %d", failures)
306				}
307				if w.writes != 1 {
308					t.Fatalf("the run must not retry an output that later could receive, got %d writes", w.writes)
309				}
310				if w.buf.Len() != firstAccept {
311					t.Fatalf("only the initially acknowledged prefix may remain, got %d bytes, want %d", w.buf.Len(), firstAccept)
312				}
313				if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
314					t.Fatalf("retained bytes must be the healthy output prefix:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
315				}
316			})
317		}
318	}
319	
320	// An output end that reports a concrete error on a long write keeps that
321	// error as the write failure's original cause: it must not be replaced by
322	// io.ErrShortWrite, whether it accepted nothing or a non-empty prefix first.
323	func TestNormalizeIOLongResultConcreteWriteErrorStaysCause(t *testing.T) {
324		line := bigSourcedLog("long-a", "")
325	
326		t.Run("nothing accepted, concrete error", func(t *testing.T) {
327			w := &failWriter{err: errSimulatedWrite}
328			failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
329			if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
330				t.Fatalf("want ErrLogWrite wrapping the concrete cause, got %v", err)
331			}
332			if errors.Is(err, io.ErrShortWrite) {
333				t.Fatalf("a concrete write error must not be replaced by io.ErrShortWrite: %v", err)
334			}
335			if failures != 0 {
336				t.Fatalf("the legal long log must not become a failure, got %d", failures)
337			}
338		})
339	
340		t.Run("prefix accepted, then concrete error", func(t *testing.T) {
341			w := &failWriter{partial: 120, err: errSimulatedWrite}
342			failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
343			if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
344				t.Fatalf("want ErrLogWrite wrapping the concrete cause, got %v", err)
345			}
346			if errors.Is(err, io.ErrShortWrite) {
347				t.Fatalf("a concrete error after a prefix must not become io.ErrShortWrite: %v", err)
348			}
349			if failures != 0 {
350				t.Fatalf("the legal long log must not become a failure, got %d", failures)
351			}
352			if w.buf.Len() != 120 {
353				t.Fatalf("the 120 bytes accepted before the error must remain, got %d", w.buf.Len())
354			}
355		})
356	}
357	
358	// On healthy output the long event completes normally, including its long
359	// extension evidence: processing runs to clean EOF with nil error, the event
360	// is valid, and event.extra carries the input's pad field verbatim.
361	func TestNormalizeIOLongResultFullDeliveryCompletes(t *testing.T) {
362		line := bigSourcedLog("long-a", "")
363		var out bytes.Buffer
364		failures, err := NormalizeReader(strings.NewReader(line+"\n"), &out)
365		if err != nil {
366			t.Fatalf("fully acknowledged long output must complete with nil error, got %v", err)
367		}
368		if failures != 0 {
369			t.Fatalf("legal long logs must report zero failures, got %d", failures)
370		}
371		results := decodeResults(t, out.Bytes())
372		if len(results) != 1 || results[0]["line"] != float64(1) || results[0]["ok"] != true {
373			t.Fatalf("the long log must be one successful result in physical line order: %#v", results)
374		}
375		event := eventOf(t, results[0])
376		if event["action"] != "long-a" {
377			t.Fatalf("long event must keep its action, got %#v", event)
378		}
379		extra, ok := event["extra"].(map[string]any)
380		if !ok {
381			t.Fatalf("long extension field must survive as event.extra, got %#v", event)
382		}
383		pad, _ := extra["pad"].(string)
384		if pad != strings.Repeat("p", 5000) {
385			t.Fatalf("extension evidence must be preserved verbatim, got pad length %d", len(pad))
386		}
387	}
388	
389	// Under the source-CIDR filter the same rules hold: a long out-of-network
390	// event is not written at all and cannot trip the output fault, a long
391	// admitted event obeys the nil-error short-write stop, and full delivery
392	// preserves its normalized content and extension evidence.
393	func TestNormalizeIOFilteredLongResultShortWrite(t *testing.T) {
394		f, err := ParseSourceCIDRFilter("192.0.2.0/24")
395		if err != nil {
396			t.Fatal(err)
397		}
398		filter := &f
399		inNet := bigSourcedLog("in-big", "192.0.2.10")
400		outNet := bigSourcedLog("out-big", "198.51.100.20")
401	
402		t.Run("long out-of-network event never touches a broken output", func(t *testing.T) {
403			w := &nilErrorPrefixWriter{allowBytes: 0}
404			failures, err := NormalizeReaderFiltered(strings.NewReader(outNet+"\n"), w, filter)
405			if err != nil {
406				t.Fatalf("a filtered-out event must not be written, so its length cannot cause a write fault, got %v", err)
407			}
408			if failures != 0 || w.writes != 0 || w.buf.Len() != 0 {
409				t.Fatalf("filtered-out long event must leave no output, no failures and no write attempts, got failures=%d writes=%d bytes=%d",
410					failures, w.writes, w.buf.Len())
411			}
412		})
413	
414		t.Run("long admitted event, zero bytes accepted", func(t *testing.T) {
415			w := &nilErrorPrefixWriter{allowBytes: 0}
416			failures, err := NormalizeReaderFiltered(strings.NewReader(inNet+"\n"), w, filter)
417			expectLongShortWriteFailure(t, w, failures, 0, 1, err)
418			if w.buf.Len() != 0 {
419				t.Fatalf("zero acknowledged bytes must leave zero output, got %q", w.buf.String())
420			}
421		})
422	
423		t.Run("long admitted event, prefix accepted", func(t *testing.T) {
424			var healthy bytes.Buffer
425			if _, err := NormalizeReaderFiltered(strings.NewReader(inNet+"\n"), &healthy, filter); err != nil {
426				t.Fatalf("test setup: healthy filtered reference run failed: %v", err)
427			}
428			w := &nilErrorPrefixWriter{allowBytes: 120}
429			failures, err := NormalizeReaderFiltered(strings.NewReader(inNet+"\n"), w, filter)
430			expectLongShortWriteFailure(t, w, failures, 0, 1, err)
431			if w.buf.Len() != 120 {
432				t.Fatalf("exactly the acknowledged prefix must remain, got %d", w.buf.Len())
433			}
434			if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
435				t.Fatalf("accepted bytes must be the unmodified prefix of healthy filtered output:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
436			}
437		})
438	
439		t.Run("long admitted event fully delivered with evidence, out-of-network one silent", func(t *testing.T) {
440			var out bytes.Buffer
441			failures, err := NormalizeReaderFiltered(strings.NewReader(outNet+"\n"+inNet+"\n"), &out, filter)
442			if err != nil {
443				t.Fatalf("healthy delivery must complete with nil error, got %v", err)
444			}
445			if failures != 0 {
446				t.Fatalf("both logs are legal; filtering does not count failures, got %d", failures)
447			}
448			results := decodeResults(t, out.Bytes())
449			if len(results) != 1 || results[0]["line"] != float64(2) || results[0]["ok"] != true {
450				t.Fatalf("only the admitted physical line 2 must be emitted, got %#v", results)
451			}
452			event := eventOf(t, results[0])
453			if event["action"] != "in-big" || event["source_ip"] != "192.0.2.10" {
454				t.Fatalf("admitted long event mismatch: %#v", event)
455			}
456			extra, ok := event["extra"].(map[string]any)
457			if !ok {
458				t.Fatalf("extension evidence must survive under the filter, got %#v", event)
459			}
460			pad, _ := extra["pad"].(string)
461			if pad != strings.Repeat("p", 5000) {
462				t.Fatalf("extension evidence must be preserved verbatim, got pad length %d", len(pad))
463			}
464			if bytes.Contains(out.Bytes(), []byte("out-big")) {
465				t.Fatalf("the out-of-network long event must leave no trace: %q", out.String())
466			}
467		})
468	}
