type faultWithBatchReader struct {
	data     []byte
	faultAt  int
	faultErr error
	pos      int
	faulted  bool
	reads    int
}

func (r *faultWithBatchReader) Read(p []byte) (int, error) {
	r.reads++
	if r.faulted {
		return 0, r.faultErr
	}
	n := copy(p, r.data[r.pos:])
	end := r.pos + n
	r.pos = end
	if end > r.faultAt { // the batch's terminating newline went out with these bytes
		r.faulted = true
		return n, r.faultErr
	}
	return n, nil
}

